    const controller = new AbortController();
    const started = performance.now();
    const running = runProcess({
      command: process.execPath,
      args: ['-e', `require('node:fs').writeFileSync(${JSON.stringify(ready)}, String(process.pid)); process.stdout.write('partial'); setInterval(() => {}, 1000);`],
